modifications.replacement_content:
// <lastmod> comes from each route's last commit date, which means a commit that
// touches a page route cannot ship its own correct sitemap: the generator has no
// way to know the date of the commit being written. Changing a route therefore
// takes two commits -- the code, then `node scripts/generate-sitemap.mjs` and the
// regenerated public/sitemap.xml. The second commit touches no route file, so it
// converges immediately. CI's --check is what makes the missing second step
// impossible to forget.
import { execFileSync } from "node:child_process";
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const base = "https://freshmobiledetail.com";
const routeDir = join(root, "src/routes");
const sitemapPath = join(root, "public/sitemap.xml");

function existingLastmods() {
  try {
    const xml = readFileSync(sitemapPath, "utf8");
    const dates = new Map();
    for (const match of xml.matchAll(
      /<url>\s*<loc>([^<]+)<\/loc>(?:\s*<lastmod>([^<]+)<\/lastmod>)?\s*<\/url>/g,
    )) {
      if (match[2]) dates.set(match[1], match[2]);
    }
    return dates;
  } catch {
    return new Map();
  }
}

const priorLastmods = existingLastmods();
const check = process.argv.includes("--check");

// A shallow clone is the dangerous case: git does not fail, it *succeeds with
// the wrong answer*. The boundary commit is parentless, and git reports a
// parentless commit as touching every file in its tree, so `log -1` returns
// HEAD's date for every route. That is the build-date fabrication this script
// exists to prevent, so treat shallow exactly like git being absent.
function gitHistoryState() {
  try {
    const shallow = execFileSync("git", ["-C", root, "rev-parse", "--is-shallow-repository"], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
    return shallow === "true" ? "shallow" : "full";
  } catch {
    return "none";
  }
}

const historyState = gitHistoryState();

function committedDate(path, route) {
  // Some builds deny child-process execution or shallow-clone. Reuse only a
  // previously committed date; checkout mtimes are build times, not
  // publication dates, and a shallow date is the build date wearing a disguise.
  if (historyState !== "full") return priorLastmods.get(`${base}${route}`) || null;
  try {
    const committed = execFileSync("git", ["-C", root, "log", "-1", "--format=%cs", "--", path], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
    return committed || priorLastmods.get(`${base}${route}`) || null;
  } catch {
    return priorLastmods.get(`${base}${route}`) || null;
  }
}

const paths = new Map();
// Routes intentionally kept out of the sitemap (noindex utility pages).
const excludedRoutes = new Set([
  "/booking-confirmed",
  "/cancellation-refund-policy",
  "/privacy-policy",
  "/terms-of-service",
]);
const routeFiles = readdirSync(routeDir).sort();
const routeFileSet = new Set(routeFiles);
for (const file of routeFiles) {
  if (
    !file.endsWith(".tsx") ||
    file.startsWith("api.") ||
    file.startsWith("[") ||
    file === "__root.tsx"
  )
    continue;
  if (file.includes("$")) continue;
  const stem = file.replace(/\.tsx$/, "");
  if (!stem.endsWith(".index") && routeFileSet.has(`${stem}.index.tsx`)) {
    continue;
  }
  let route = file
    .replace(/\.tsx$/, "")
    .replace(/\.index$/, "")
    .replaceAll(".", "/");
  route = route === "index" ? "/" : `/${route}`;
  if (excludedRoutes.has(route)) continue;
  paths.set(route, committedDate(`src/routes/${file}`, route));
}

const citySource = readFileSync(join(root, "src/components/CityPage.tsx"), "utf8");
for (const match of citySource.matchAll(/\n\s+slug:\s+"([^"]+)"/g)) {
  const route = `/areas/${match[1]}`;
  paths.set(route, committedDate("src/components/CityPage.tsx", route));
}

const legacyBlogSource = readFileSync(join(root, "src/routes/blog.$slug.tsx"), "utf8");
for (const match of legacyBlogSource.matchAll(/\n\s+slug:\s+"([^"]+)"/g)) {
  const route = `/blog/${match[1]}`;
  paths.set(route, committedDate("src/routes/blog.$slug.tsx", route));
}

const contentDir = join(root, "content/blog");
for (const file of readdirSync(contentDir)
  .filter((name) => name.endsWith(".json"))
  .sort()) {
  const post = JSON.parse(readFileSync(join(contentDir, file), "utf8"));
  paths.set(`/blog/${post.slug}`, post.date_published);
}

const urls = [...paths.entries()]
  .sort(([left], [right]) => left.localeCompare(right))
  .map(([path, lastmod]) =>
    [
      "  <url>",
      `    <loc>${base}${path}</loc>`,
      ...(lastmod ? [`    <lastmod>${lastmod}</lastmod>`] : []),
      "  </url>",
    ].join("\n"),
  );

const xml = [
  '<?xml version="1.0" encoding="UTF-8"?>',
  '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
  ...urls,
  "</urlset>",
  "",
].join("\n");

if (check) {
  // Without full history the expected <lastmod> for every git-derived route
  // falls back to priorLastmods, which was parsed from the very file being
  // compared. The check would then pass against an objectively drifted sitemap.
  // Refuse rather than self-certify.
  if (historyState !== "full") {
    console.error(
      historyState === "shallow"
        ? "sitemap check needs full history: a shallow clone reports the boundary commit's date for every path. Use actions/checkout with fetch-depth: 0."
        : "sitemap check needs git: without it every expected <lastmod> is read back from the file under test.",
    );
    process.exit(1);
  }
  let committed = "";
  try {
    committed = readFileSync(sitemapPath, "utf8");
  } catch {
    console.error("sitemap drift: public/sitemap.xml is missing");
    process.exit(1);
  }
  if (committed !== xml) {
    const oldLines = committed.split("\n");
    const newLines = xml.split("\n");
    console.error("sitemap drift: run `node scripts/generate-sitemap.mjs`");
    const limit = Math.max(oldLines.length, newLines.length);
    for (let index = 0; index < limit; index += 1) {
      if (oldLines[index] !== newLines[index]) {
        console.error(`- ${oldLines[index] ?? "<missing>"}`);
        console.error(`+ ${newLines[index] ?? "<missing>"}`);
      }
    }
    process.exit(1);
  }
  console.log(`sitemap is current with ${urls.length} URLs`);
} else {
  writeFileSync(sitemapPath, xml, "utf8");
  console.log(`generated sitemap with ${urls.length} URLs`);
}
